export interface ValidationRule {
  field: string;
  test: (value: unknown) => boolean;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: { field: string; message: string }[];
}

export function validate(data: Record<string, unknown>, rules: ValidationRule[]): ValidationResult {
  const errors: { field: string; message: string }[] = [];
  for (const rule of rules) {
    const value = data[rule.field];
    if (!rule.test(value)) {
      errors.push({ field: rule.field, message: rule.message });
    }
  }
  return { valid: errors.length === 0, errors };
}

export function required(field: string, message?: string): ValidationRule {
  return {
    field,
    test: (v: unknown) => v !== undefined && v !== null && v !== '',
    message: message || `${field} is required`,
  };
}

export function minLength(field: string, min: number, message?: string): ValidationRule {
  return {
    field,
    test: (v: unknown) => typeof v === 'string' && v.length >= min,
    message: message || `${field} must be at least ${min} characters`,
  };
}

export function isEmail(field: string, message?: string): ValidationRule {
  return {
    field,
    test: (v: unknown) => typeof v === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
    message: message || `${field} must be a valid email`,
  };
}

