{"path":"src/validator.test.ts","content":"import { validate, required, minLength, isEmail } from './validator';

describe('validate', () => {
  it('returns valid=true when all rules pass', () => {
    const result = validate({ name: 'Alice', email: 'a@b.com' }, [required('name'), isEmail('email')]);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  it('returns valid=false with error messages', () => {
    const result = validate({ name: '' }, [required('name')]);
    expect(result.valid).toBe(false);
    expect(result.errors[0].field).toBe('name');
  });

  it('handles empty data object', () => {
    const result = validate({}, [required('name')]);
    expect(result.valid).toBe(false);
  });

  it('handles null/undefined values', () => {
    const r1 = validate({ name: null }, [required('name')]);
    expect(r1.valid).toBe(false);
    const r2 = validate({ name: undefined }, [required('name')]);
    expect(r2.valid).toBe(false);
  });

  it('collects multiple errors', () => {
    const result = validate({}, [required('name'), required('email'), minLength('bio', 10)]);
    expect(result.errors).toHaveLength(3);
  });
});

describe('required', () => {
  it('rejects empty string', () => expect(required('x').test('')).toBe(false));
  it('rejects null', () => expect(required('x').test(null)).toBe(false));
  it('accepts non-empty string', () => expect(required('x').test('hi')).toBe(true));
  it('accepts number 0', () => expect(required('x').test(0)).toBe(true));
});

describe('minLength', () => {
  it('rejects short string', () => expect(minLength('x', 5).test('abc')).toBe(false));
  it('accepts exact length', () => expect(minLength('x', 3).test('abc')).toBe(true));
  it('accepts longer string', () => expect(minLength('x', 3).test('abcd')).toBe(true));
  it('rejects non-string', () => expect(minLength('x', 3).test(123)).toBe(false));
});

describe('isEmail', () => {
  it('accepts valid email', () => expect(isEmail('e').test('a@b.com')).toBe(true));
  it('rejects missing @', () => expect(isEmail('e').test('ab.com')).toBe(false));
  it('rejects missing domain', () => expect(isEmail('e').test('a@')).toBe(false));
  it('rejects empty string', () => expect(isEmail('e').test('')).toBe(false));
  it('rejects non-string', () => expect(isEmail('e').test(123)).toBe(false));
});
